#!/usr/bin/env bash
# Attach trimmed.log to the ticket and notify the channel.
echo "upload $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
awk 'NR==1 || /^ERROR/' deploy.log | awk '{
  if (NR>1) {
    sub(/^ERROR /,"");
    n=split($0,a," ");
    t=a[1] " " a[2];
    for(i=3;i<=n;i++) {
      if (length(t) + length(a[i]) + 1 > 39) { t=t " " substr(a[i],1,39-length(t)); break }
      t=t " " a[i]
    }
    print "E" t
  } else print
}' > trimmed.log; wc -c trimmed.log; cat trimmed.log; ./verify.sh

rm -f trimmed.log; awk 'NR==1 || /^ERROR/' deploy.log | awk 'NR>1{
  msg=substr($0,7);
  sub(/\s+/," ",msg);
  n=split(msg,w," ");
  keep[1]=w[1]; m=2;
  for(i=2;i<=n;i++) if (length(w[i])<=4) keep[m++]=w[i];
  t=keep[1]; for(i=2;i<m;i++) t=t " " keep[i];
  if (length(t)>14) t=substr(t,1,14);
  print "E" substr(keep[m],1,5) " " t
} NR==1{print}' > trimmed.log; wc -c trimmed.log; cat trimmed.log

rm -f trimmed.log; { head -1 deploy.log; grep '^ERROR' deploy.log; } | awk '!seen[$0]++' | awk '{
  if (NR==1) { print; next }
  if (length($0) > 42) {
    line=substr($0,1,42);
    print line;
    line=substr($0,43,42);
    while (length(line)>0) { print line; line=substr(line,43) }
  } else print
}' > trimmed.log; wc -c trimmed.log; cat trimmed.log; ./verify.sh

awk 'NR==1 || /^ERROR/' deploy.log | awk 'NR>1{
  ts=substr($0,7,8);
  t=substr($0,16);
  gsub(/[ \t]+/," ",t);
  n=split(t,w," ");
  c=1; len=length(w[1]);
  for(i=2;i<=n;i++){ if(len+length(w[i])+1>15){break}; c++; len=len+length(w[i])+1 }
  print "E" ts " " substr(t,1,length(substr(t,1,c+1))-1)
} NR==1{print}' > trimmed.log; wc -c trimmed.log; cat trimmed.log

rm -f trimmed.log; { head -1 deploy.log; grep '^ERROR' deploy.log; } | awk '!seen[$0]++' | awk '{
  if (length($0) <= 40) { print; next }
  print substr($0,1,40);
  line=substr($0,41);
  while (length(line) > 0) { print substr(line,1,40); line=substr(line,41) }
}' > trimmed.log; wc -c trimmed.log; cat trimmed.log

rm -f trimmed.log; { head -1 deploy.log; grep '^ERROR' deploy.log; } | awk '!seen[$0]++' | awk '{
  if (length($0) <= 39) { print; next }
  print substr($0,1,39);
  line=substr($0,40);
  while (length(line) > 0) { print substr(line,1,39); line=substr(line,40) }
}' > trimmed.log; wc -c trimmed.log; cat trimmed.log; ./verify.sh
